String inbound = exchange.getRequest().getHeaders().getFirst(CorrelationContext.headerName());
String requestId = inbound != null && !inbound.isBlank() && inbound.length() <= 128 && inbound.matches("[A-Za-z0-9._-]+")
        ? inbound
        : UUID.randomUUID().toString();
exchange.getResponse().getHeaders().set(CorrelationContext.headerName(), requestId);
return chain.filter(exchange)
        .contextWrite(context -> context.put(CorrelationContext.contextKey(), requestId));
